Set<int> fn0(String logs) {
  Set<int> alerts = {};
  int lastColon = logs.lastIndexOf(':');
  if (lastColon < 0) {
    return alerts;
  }
  String line = logs.substring(0, lastColon);
  int depth = 0;
  String level = '';
  for (int i = 0; i < line.length; i++) {
    if (line[i] == '[') {
      depth++;
    } else if (line[i] == ']') {
      depth--;
    } else if (line[i] == '^') {
      level = depth == 0 ? 'critical' : (depth == 1 ? 'warning' : 'info');
      break;
    }
  }
  if (level.isEmpty) {
    return alerts;
  }
  lastColon = line.lastIndexOf(':');
  if (lastColon < 0) {
    return alerts;
  }
  String time = line.substring(lastColon + 1);
  int colon = time.indexOf(':');
  if (colon < 0) {
    return alerts;
  }
  String hour = time.substring(0, colon);
  int colon2 = time.indexOf(':', colon + 1);
  if (colon2 < 0) {
    return alerts;
  }
  String minute = time.substring(colon + 1, colon2);
  int hourVal = int.tryParse(hour);
  int minuteVal = int.tryParse(minute);
  if (hourVal == null || minuteVal == null || hourVal < 0 || minuteVal < 0) {
    return alerts;
  }
  if (level == 'critical' && hourVal >= 23) {
    alerts.add(hourVal * 60 + minuteVal);
  } else if (level == 'warning' && hourVal >= 17 && hourVal <= 22) {
    alerts.add(hourVal * 60 + minuteVal);
  }
  return alerts;
}

