List<bool> wordBreak(String s, List<String> wordDict, [String word = ""]) {
  List<bool> dp = List.filled(s.length, false);
  Set<String> wordSet = wordDict.toSet();
  List<List<int>> seg = [];

  for (int i = 0; i < s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j + 1, i + 1))) {
        dp[i] = true;
        break;
      }
    }
  }

  if (dp[s.length - 1]) {
    seg.add([]);
  }

  for (int i = s.length - 1; i >= 0; i--) {
    if (dp[i]) {
      for (int j = i + 1; j < s.length; j++) {
        if (dp[j]) {
          if (wordSet.contains(s.substring(i + 1, j + 1))) {
            seg.add([i + 1, j + 1]);
          }
        }
      }
    }
  }

  seg.sort((a, b) {
    int lenA = a[1] - a[0] + 1;
    int lenB = b[1] - b[0] + 1;
    if (lenA != lenB) return lenA.compareTo(lenB);
    return a[0].compareTo(b[0]);
  });

  return dp;
}

