    } else if (cmd == 'UNDO') {
      pop();
    } else if (cmd.startsWith('BEGIN')) {
      String color = cmd.substring(5);
      push(color, int.parse(cmd.substring(6)));
    }
  }

  report.add('BEGIN');
  for (String color in ['RED', 'GREEN', 'BLUE']) {
    report.add('${color}:${totals[color]}');
  }
  report.add('END');

  List<String> parts = report.split('/');
  parts.sort();
  return parts;
}

