bool fn0(List<List<int>> grid, int k) {
  if (grid.isEmpty || grid[0].isEmpty) {
    return false;
  }
  int rows = grid.length;
  int cols = grid[0].length;
  if (rows < 2 || cols < 2) {
    return false;
  }

  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (r == 0 && c == 0) {
        dp[r][c] = grid[r][c];
      } else {
        int left = (c > 0) ? dp[r][c - 1] : 0;
        int above = (r > 0) ? dp[r - 1][c] : 0;
        int diagonal = (r > 0 && c > 0) ? dp[r - 1][c - 1] : 0;
        dp[r][c] = grid[r][c] + left + above + diagonal;
      }
    }
  }

  int maxVal = dp[rows - 1][cols - 1];
  if (k <= maxVal) {
    return true;
  }

  for (int r = rows - 1; r >= 0; r--) {
    for (int c = cols - 1; c >= 0; c--) {
      if (dp[r][c] > k) {
        break;
      }
      int left = (c > 0) ? dp[r][c - 1] : 0;
      int above = (r > 0) ? dp[r - 1][c] : 0;
      int diagonal = (r > 0 && c > 0) ? dp[r - 1][c - 1] : 0;
      int cost = grid[r][c] + left + above + diagonal;
      if (cost <= k) {
        return true;
      }
    }
  }
  return false;
}

