int nChooseK(int n, int k) {
  if (k > n || k < 0) return 0;
  if (k == 0 || k == n) return 1;

  final int factN = nFactorial(n);
  final int factK = kFactorial(k);
  final int factNK = nFactorial(n - k);

  return factN ~/ (factK * factNK);
}

int nFactorial(int n) {
  if (n < 0) return 0;
  int result = 1;
  for (int i = 1; i <= n; i++) {
    result *= i;
  }
  return result;
}

int kFactorial(int k) {
  if (k < 0) return 0;
  int result = 1;
  for (int i = 1; i <= k; i++) {
    result *= i;
  }
  return result;
}

