        current.add(numbers[i]);
        backtrack(i + 1, current, used);
        current.removeLast();
        used[i] = false;
      }
    }
  }

  List<bool> used = List.filled(numbers.length, false);

  backtrack(0, [], used);

  print('Total combinations: $totalCombinations');
