      counts[nextSuit] = (counts[nextSuit]! + 1) % 4;
    }

    int len = rank.length;
    if (len > maxLen) maxLen = len;
  }

  int maxCount = 0;
  for (int v in counts.values) {
    if (v > maxCount) maxCount = v;
  }

