List<String> fn0(List<String> logs, List<String> targets) {
  List<String> results = [];
  if (logs.isEmpty || targets.isEmpty) return results;
  int n = logs.length;
  int m = targets.length;
  if (m == 0) return results;

  Map<String, int> logIdx = {};
  for (int i = 0; i < n; i++) {
    String id = logs[i];
    logIdx[id] = i;
  }
  if (logIdx.isEmpty) return results;

  List<List<int>> queries = [];
  for (String target in targets) {
    int idx = logIdx[target]!;
    if (idx == -1) continue;
    queries.add([idx, 0, 0, 1]);
  }

  int left = 0;
  int right = n - 1;
  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    bool enough = false;
    for (List<int> q in queries) {
      if (q[1] <= mid) {
        if (q[3] > 0) {
          enough = true;
          break;
        }
        q[3] = 0;
      } else if (q[2] <= mid) {
        q[3] = q[3] + 1;
      }
    }
    if (enough) {
      results.add(logs[mid]);
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  results.sort();
  return results;
}

