List<int> fn0(List<String> cells) {
  final List<int> result = [];
  if (cells.isEmpty) return result;

  final Set<String> visited = {};
  bool hasSolution = false;

  for (final String cell in cells) {
    if (cell.isEmpty) continue;

    final List<String> parts = cell.split('|');
    if (parts.length != 2) continue;

    final String row = parts[0];
    final List<String> positions = parts[1].split(',');

    if (row.isEmpty || positions.isEmpty) continue;

    final List<String> open = [];
    final List<String> closed = [];
    final List<List<int>> coords = [];

    for (final String pos in positions) {
      if (pos.isEmpty) continue;

      final List<String> p = pos.split(',');
      if (p.length != 2) continue;

      final int x = int.parse(p[0]);
      final int y = int.parse(p[1]);

      if (x >= row.length || y >= row.length) continue;

      final String key = '$row,$x,$y';
      if (visited.contains(key)) continue;

      visited.add(key);
      open.add('$row,$x,$y');
      coords.add([x, y]);
    }

    if (open.isEmpty) continue;

    while (open.isNotEmpty) {
      final List<String> nextOpen = [];
      final List<String> newClosed = [];

      for (final String cell in open) {
        final List<String> parts = cell.split(',');
        final int x = int.parse(parts[0]);
        final int y = int.parse(parts[1]);

        final String key = '$row,$x,$y';
        if (closed.contains(key)) continue;

        closed.add(key);

        for (final int d = 1; d <= 4; d++) {
          final int nx = x + d;
          final int ny = y + d;

          if (nx < 0 || nx >= row.length || ny < 0 || ny >= row.length) continue;

          final String nKey = '$row,$nx,$ny';
          if (visited.contains(nKey)) continue;

          visited.add(nKey);
          nextOpen.add('$row,$nx,$ny');
        }
      }

      open = nextOpen;
    }

    if (closed.length == row.length * row.length) {
      hasSolution = true;
      break;
    }
  }

  if (!hasSolution) {
    result.add(-1);
    return result;
  }

  final List<List<int>> sorted = [...coords];
  sorted.sort((a, b) {
    final int distA = (a[0] - 0).abs() + (a[1] - 0).abs();
    final int distB = (b[0] - 0).abs() + (b[1] - 0).abs();
    if (distA != distB) return distA.compareTo(distB);
    return a[0].compareTo(b[0]);
  });

  for (final List<int> cell in sorted) {
    result.add(cell[0] * row.length + cell[1]);
  }

  return result;
}

