  }
  int left = 0;
  int right = songDurations.length - 1;
  int answerPairCount = 0;
  int answerMashupDuration = 0;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    int currentSum = 0;
    for (int i = 0; i <= mid; i++) {
      currentSum += songDurations[i];
    }
    if (currentSum < targetDuration) {
      left = mid + 1;
    } else {
      right = mid - 1;
      answerPairCount += mid - left + 1;
      answerMashupDuration += currentSum - songDurations[left];
    }
  }
  return {'pairCount': answerPairCount, 'mashupDuration': answerMashupDuration};
}

