      (2 * Math.pi * (Math.random())).sin() * 2.0,
      (2 * Math.pi * (Math.random())).sin() * 2.0,
      Math.random() * 2.0 - 1.0);

  const Quaternion.fromList(List<double> list)
      : this(list[0], list[1], list[2], list[3]);

  double length() {
    return (x * x + y * y + z * z + w * w).sqrt();
  }

  double norm() {
    return (x * x + y * y + z * z + w * w).sqrt();
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion invert() {
    if (w == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(x, y, z, 1.0 / w);
  }

  Quaternion rotateZ(double angle) {
    double sinA = angle.sin();
    double cosA = angle.cos();
    double x = (x * sinA + y * cosA) * 2.0;
    double y = (-x * cosA + y * sinA) * 2.0;
    return Quaternion(x, y, z, w);
  }

  Quaternion rotateY(double angle) {
    double sinA = angle.sin();
    double cosA = angle.cos();
    double z = (z * sinA + w * cosA) * 2.0;
    double w = (-z * cosA + w * sinA) * 2.0;
    return Quaternion(x, y, z, w);
  }

  Quaternion rotateX(double angle) {
    double sinA = angle.sin();
    double cosA = angle.cos();
    double w = (w * sinA + x * cosA) * 2.0;
    double x = (-w * cosA + x * sinA) * 2.0;
    return Quaternion(x, y, z, w);
  }

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

