class Quaternion {
  final double x, y, z, w;
  static const double EPSILON = 1.0e-6;

  const Quaternion(this.x, this.y, this.z, this.w);

  static const Quaternion zero = const Quaternion(0.0, 0.0, 0.0, 1.0);

  const Quaternion.unit = const Quaternion(0.0, 0.0, 0.0, 1.0);

  const Quaternion.fromList(List<double> list) : this(list[0], list[1], list[2], list[3]);

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ, double angle) {
    final sinA = 2.0 * angle * sin(angle);
    return const Quaternion(
      axisX * sinA + (1.0 - sinA) * 0.5,
      axisY * sinA + (1.0 - sinA) * 0.5,
      axisZ * sinA + (1.0 - sinA) * 0.5,
      sinA * 0.5,
    );
  }

  Quaternion operator +(const Quaternion other) => const Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(const Quaternion other) => const Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(const Quaternion other) =>
      const Quaternion(
        (x * other.w) - (other.x * w) + (y * other.z) - (other.y * z),
        (y * other.w) - (other.y * w) + (z * other.x) - (other.z * x),
        (z * other.w) - (other.z * w) + (x * other.y) - (other.x * y),
        other.w * w,
      );

  Quaternion operator ^(int n) => n == 0 ? this : this * other ^ (n - 1);

  Quaternion conjugate() => const Quaternion(x, y, z, -w);

  double norm() => (x * x + y * y + z * z + w * w);

  Quaternion normalized() => this / norm();

  @override
  String toString() => 'q$x + q$y i + q$z j + q$w k';
}

