class Quaternion {
  double x;
  double y;
  double z;
  double w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion.identity() : this(0.0, 0.0, 0.0, 1.0);

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  Quaternion.random() {
    final rand = Random(0);
    return Quaternion(
      rand.nextFloat() * 2 - 1,
      rand.nextFloat() * 2 - 1,
      rand.nextFloat() * 2 - 1,
      rand.nextFloat() * 2 - 1,
    );
  }

  @override
  String toString() =>
      '${x.toStringAsFixed(2)} + ${y.toStringAsFixed(2)}i + ${z.toStringAsFixed(2)}j + ${w.toStringAsFixed(2)}k';

  double magnitude() => sqrt(x * x + y * y + z * z + w * w);

  void normalize() {
    final mag = magnitude();
    if (mag == 0.0) {
      x = 0.0;
      y = 0.0;
      z = 0.0;
      w = 1.0;
      return;
    }
    final invMag = 1.0 / mag;
    x *= invMag;
    y *= invMag;
    z *= invMag;
    w *= invMag;
  }

  Quaternion inverse() {
    final mag = x * x + y * y + z * z + w * w;
    final invMag = 1.0 / mag;
    return Quaternion(-x * invMag, -y * invMag, -z * invMag, w * invMag);
  }

  Quaternion conjugate() =>
      Quaternion(x, y, z, -w);

  Quaternion operator * (double scalar) {
    final t = Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
    return t;
  }

  Quaternion operator * (Quaternion other) {
    final t = Quaternion(
      x * other.w - y * other.z - z * other.y + w * other.x,
      y * other.w + x * other.z + z * other.y - w * other.x,
      z * other.w + w * other.y - x * other.z + y * other.x,
      w * other.w,
    );
    return t;
  }

  static Quaternion operator +(Quaternion a, Quaternion b) {
    final x = a.x + b.x;
    final y = a.y + b.y;
    final z = a.z + b.z;
    final w = a.w + b.w;
    return Quaternion(x, y, z, w);
  }

  static Quaternion operator -(Quaternion a, Quaternion b) {
    final x = a.x - b.x;
    final y = a.y - b.y;
    final z = a.z - b.z;
    final w = a.w - b.w;
    return Quaternion(x, y, z, w);
  }

  void rotateAroundZ(double theta) {
    final sin = sin(theta);
    final cos = cos(theta);
    final t = Quaternion(
      cos * x + sin * y - z * w,
      sin * x + cos * y + z * w,
      -z * cos + w * sin,
      sin * w,
    );
    x = t.x;
    y = t.y;
    z = t.z;
    w = t.w;
  }
}

