double fn0(List<String> ops, int nBase) {
  List<int> stack = [];
  List<List<int>> history = [];
  int product = 1;
  int digitSum = 0;
  bool valid = true;

  for (String op in ops) {
    if (op == 'B') {
      stack.add(0);
      history.add([0]);
    } else if (op == 'D' || op == 'M') {
      if (stack.isEmpty) {
        valid = false;
        break;
      }
      history.add([stack.removeLast(), stack.last]);
    } else if (op == 'P' || op == 'R') {
      if (stack.length < 2) {
        valid = false;
        break;
      }
      int b = stack.removeLast();
      int a = stack.removeLast();
      if (op == 'P') {
        stack.add(a * b);
        history.add([a, b, stack.last]);
      } else {
        stack.add(a ~/ b);
        history.add([a, b, stack.last]);
      }
    } else if (op == 'S') {
      if (stack.isEmpty) {
        valid = false;
        break;
      }
      int last = stack.last;
      if (last < 0) {
        valid = false;
        break;
      }
      List<int> digits = [];
      int n = last;
      while (n > 0) {
        digits.add(n % nBase);
        n ~/= nBase;
      }
      history.add([last, ...digits]);
      for (int d in digits) {
        product *= d;
        digitSum += d;
      }
    } else if (op == 'C' || op == 'X' || op == 'Z') {
      if (stack.isNotEmpty) {
        int last = stack.last;
        if (op == 'X') {
          stack.add(last * 2);
        } else if (op == 'Z') {
          stack.add(last ~/ 2);
        } else {
          int first = stack.first;
          stack.add(first < last ? first : last);
        }
      }
    }
  }

  if (!valid || stack.isNotEmpty) {
    return 0.0;
  }

  List<int> digits = [];
  int n = digitSum;
  while (n > 0) {
    digits.add(n % nBase);
    n ~/= nBase;
  }
  history.add([digitSum, ...digits]);

  List<List<int>> allHistory = [];
  List<int> result = [];
  while (stack.isNotEmpty) {
    result.add(stack.removeLast());
  }
  allHistory.addAll(history);

  double total = 0.0;
  for (int i = 0; i < allHistory.length - 1; i++) {
    if (allHistory[i].length == allHistory[i + 1].length) {
      total += (allHistory[i][allHistory[i].length - 1] - allHistory[i + 1][allHistory[i + 1].length - 1]).abs().toDouble();
    }
  }

  return (product + total) / 2.0;
}

