    for (String cell in cells) {
      if (cell.isEmpty) {
        continue;
      }

      String type = cell[0];
      String dataStr = '';
      for (int i = 1; i < cell.length; i++) {
        dataStr += cell[i];
      }

      if (type == 'S') {
        rowData.add(1);
      } else if (type == 'P') {
        rowData.add(2);
      } else if (type == 'R') {
        rowData.add(3);
      } else if (type == 'M') {
        rowData.add(4);
      } else if (type == 'D') {
        rowData.add(5);
      } else if (type == 'C') {
        rowData.add(6);
      } else if (type == 'B') {
        rowData.add(7);
      } else {
        continue;
      }

      if (dataStr.isNotEmpty) {
        int count = 0;
        for (int i = 0; i < dataStr.length; i++) {
          int c = dataStr.codeUnitAt(i);
          if (c >= 48 && c <= 57) {
            count = count * 10 + c - 48;
          }
        }
        rowData.addAll(List.filled(count, dataStr.codeUnitAt(0)));
      }
    }
    data.add(rowData);
  }

  double score = 0.0;
  for (int i = 0; i < data.length; i++) {
    List<int> row = data[i];

    bool rowHasBorder = false;
    for (int j = 1; j < row.length; j++) {
      if (row[j] == 7) {
        rowHasBorder = true;
        break;
      }
    }
    if (rowHasBorder) {
      score += 2.0;
      continue;
    }

    bool rowHasPeaks = false;
    bool rowHasDeltas = false;
    bool rowHasSeeds = false;
    bool rowHasCycles = false;

    for (int j = 1; j < row.length; j++) {
      if (row[j] >= 97 && row[j] <= 122) {
        rowHasSeeds = true;
      }

      if (row[j - 1] >= 48 && row[j - 1] <= 57 && row[j] >= 48 && row[j] <= 57) {
        rowHasDeltas = true;
      }

      if (row[j] == row[j - 1]) {
        rowHasPeaks = true;
      }

      if (j >= 2 && row[j] != row[j - 2] && row[j] != row[j - 1]) {
        rowHasCycles = true;
      }
    }

    if (rowHasSeeds && rowHasDeltas) {
      score += 1.0;
    }
    if (rowHasSeeds && rowHasCycles) {
      score += 1.0;
    }
    if (rowHasPeaks) {
      score += 0.5;
    }
  }

  return score;
}

