    for (int i = n ~/ 2; i < n; i++) {
      if (values[i] > values[i + 1]) {
        secondHalfMonotone = false;
      }
    }
    if (firstHalfMonotone && secondHalfMonotone) {
      int mid = keys[(n ~/ 2) - 1];
      int low = 0;
      int high = n - 1;
      while (low < high) {
        int midLow = (low + high) ~/ 2;
        int midHigh = (low + high + 1) ~/ 2;
        if (counts[keys[midLow]]! >= midHigh) {
          low = midLow + 1;
        } else {
          high = midLow;
        }
      }
      if (low == n ~/ 2 - 1) return false;
    }
  }
  return true;
}

