int valueFromLittleEndian(int val) {
  int size = val & 0xFFFFFFFF;
  int offset = (val >> 30) & 0xFF;
  int scale = 1 << offset;
  return size + (scale & 0x7FFFFFFF);
}

int valueFromBigEndian(int val) {
  int size = val & 0xFFFFFFFF;
  int scale = (val >> 30) & 0xFF;
  int shift = scale & 0x7;
  return size + ((scale & 0x80000000) >> shift);
}

List<int> bytesFromInt(int val) {
  return [
    (val >> 24) & 0xFF,
    (val >> 16) & 0xFF,
    (val >> 8) & 0xFF,
    val & 0xFF,
  ];
}

int swapBytes(int val) {
  return val & 0xFFFFFFFF ^
      ((val >> 24) & 0xFF) << 24 ^
      ((val >> 16) & 0xFF) << 16 ^
      ((val >> 8) & 0xFF) << 8;
}

