    if (resourcePermissionCache.containsKey(resource)) {
      return resourcePermissionCache[resource]!;
    }

    final Map<String, bool> permissions = {};
    for (var role in roles.keys) {
      for (var permission in roles[role]!) {
        if (permission == 'admin') {
          permissions['$resource/$role'] = true;
          continue;
        }
        if (permission == 'read' || permission == 'write' || permission == 'delete') {
          permissions['$resource/$role'] = true;
        }
      }
    }

    final Map<String, String> roleHierarchy = {};
    for (var role in roles.keys) {
      if (roles[role]!.contains('admin')) {
        roleHierarchy[role] = 'admin';
