    if (hex.length != bits) {
      throw ArgumentError('Hex string must have exactly $bits characters');
    }
    int value = 0;
    for (int i = 0; i < bits; i++) {
      int digit = hex.codeUnitAt(i) - 48;
      value |= digit << (bits - 1 - i);
    }
    return value;
  }

