int packInt(int value, Endian endian) {
  int bytes;
  if (endian == Endian.little) {
    bytes = [
      (value >> 16) & 0xFF,
      value & 0xFF
    ];
  } else {
    bytes = [
      value & 0xFF,
      (value >> 16) & 0xFF
    ];
  }
  return bytes.fold(0, (acc, b) => acc * 256 + b);
}

int unpackInt(int bytes, Endian endian) {
  int value;
  if (endian == Endian.little) {
    value = (bytes >> 16) & 0xFFFF;
  } else {
    value = bytes & 0xFFFF;
  }
  return value;
}

int swap16(int value) {
  int sw = ((value >> 8) & 0xFF) | (value << 8);
  int sw2 = ((sw >> 8) & 0xFF) | (sw << 8);
  return sw2;
}

int swap32(int value) {
  int sw = ((value >> 24) & 0xFF) |
      ((value >> 8) & 0xFF) << 24) |
      ((value << 8) & 0xFF) << 16);
  int sw2 = ((sw >> 24) & 0xFF) |
      ((sw >> 8) & 0xFF) << 16) |
      ((sw << 8) & 0xFF) << 8);
  return sw2;
}

