class PointSet {
  final List<Point> points;
  final double radius;

  PointSet(this.points, this.radius);

  bool contains(Point p) => radius == 0 ? true : Point.pointInCircle(p, points[0], radius);

  bool contains(List<Point> pts) =>
      points.isEmpty ? false : pts.contains(points[0]);

  bool contains(Rectangle rect) =>
      contains(rect.point1) &&
      contains(rect.point2) &&
      (rect.x1 < points[0].x - radius ||
          rect.x2 > points[0].x + radius ||
          rect.y1 < points[0].y - radius ||
          rect.y2 > points[0].y + radius);

  bool intersects(Rectangle rect) =>
      rect.contains(points[0]) &&
      (rect.x1 < points[0].x - radius ||
          rect.x2 > points[0].x + radius ||
          rect.y1 < points[0].y - radius ||
          rect.y2 > points[0].y + radius);

  bool get isFinite => points.isNotEmpty;

  @override
  String toString() => 'PointSet(${points.length} points, radius $radius)';
}

