    [5.0, 5.0],
    [7.0, 2.0]
  ];

  double eps = double.infinity;
  int minPts = 2;

  List<List<double>> centroids = List.generate(k, (_) => [rand.nextDouble() * 10 - 5, rand.nextDouble() * 10 - 5]);

  List<int> labels = List.filled(points.length, -1);

  Set<int> clusterIds = {};

  bool pointInCluster(int idx) {
    double dist = double.infinity;
    for (var c in centroids) {
      double d = (points[idx][0] - c[0]).abs() + (points[idx][1] - c[1]).abs();
      if (d <= eps && d < dist) {
        dist = d;
      }
    }
    return dist <= eps;
  }

  void expandCluster(int idx, List<int> neighbors, int clusterId) {
    labels[idx] = clusterId;

    for (int i = 0; i < neighbors.length; i++) {
      if (labels[neighbors[i]] == -1) {
        labels[neighbors[i]] = clusterId;
        clusterIds.add(clusterId);
        neighbors.add(neighbors[i]);
      } else if (labels[neighbors[i]] == 0) {
        neighbors.removeAt(i);
      }
    }
  }

  for (int i = 0; i < points.length; i++) {
    if (labels[i] != -1) continue;

    labels[i] = 0;
    clusterIds.add(0);

    List<int> neighbors = [];

    for (int j = 0; j < points.length; j++) {
      if (j == i) continue;
      if (pointInCluster(j)) {
        neighbors.add(j);
      }
    }

    if (neighbors.length >= minPts) {

      List<List<double>> clusterPoints = List.from(points);
      clusterPoints.removeAt(i);

      centroids[0] = [0.0, 0.0];

      for (var p in clusterPoints) {
