        centroids[0][1] += p[1];
      }
      centroids[0][0] /= clusterPoints.length;
      centroids[0][1] /= clusterPoints.length;

      for (int j = 0; j < points.length; j++) {
        if (j != i && pointInCluster(j)) {
          expandCluster(j, neighbors, 0);
        }
      }
    }
  }

  int iter = 0;
  List<List<int>> pointsInCluster = List.generate(k, (_) => []);

  for (int i = 0; i < points.length; i++) {
    if (labels[i] != -1) continue;
    if (labels[i] == 0) continue;
    pointsInCluster[labels[i]].add(i);
  }

  print('Cluster IDs: $clusterIds');
  print('Converged in $iter iteration(s).');
