      sum += diff * diff;
    }
    return sum;
  }

  List<double> centroid(List<int> points) {
    if (points.isEmpty) return [0.0, 0.0];
    double sumX = 0, sumY = 0;
    for (final p in points) {
      sumX += p[0];
      sumY += p[1];
    }
    return [sumX / points.length, sumY / points.length];
  }

  int assigned(List<int> points) {
    double minDist = double.infinity;
    int best = -1;
    for (int i = 0; i < points.length; i++) {
      double d = distance(points, clusters[i]);
      if (d < minDist) {
        minDist = d;
        best = i;
      }
    }
    return best;
  }

  int clusterId = 0;
  for (final p in points) {
    clusters[assigned(p)] = [clusterId];
  }

  double newDistance(List<double> a, List<double> b) {
    double sum = 0;
    for (int i = 0; i < a.length; i++) {
      double diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sum;
  }

