  List<List<int>> intervals = [];
  for (int i = 0; i < numIngredients; i++) {
    if (ingredients[i].isEmpty) continue;
    int lo = 0;
    int hi = numAmounts - 1;
    while (lo < hi) {
      int mid = (lo + hi) >> 1;
      if (amounts[mid] >= amounts[i]) {
        hi = mid;
      } else {
        lo = mid + 1;
      }
    }
    intervals.add([lo, hi]);
  }

  Map<String, int> result = {};
  for (int i = 0; i < numIngredients; i++) {
    int lo = intervals[i][0];
    int hi = intervals[i][1];
    if (lo > hi) {
      continue;
    }
    for (int j = i + 1; j < numIngredients; j++) {
      int lj = intervals[j][0];
      int rj = intervals[j][1];
      if (lj <= lo && rj >= hi) {
        String key = ingredients[i] + '—' + ingredients[j];
        int count = (result[key] ?? 0) + 1;
        result[key] = count;
      }
    }
  }
  return result;
}

